mapper.sql:
NOT EXISTS (SELECT 1
            FROM task_seen ts
            WHERE ts.user_id = #{userId}
              AND ts.course_id = #{courseId}
              AND ts.mission_id = m.mission_id)

mapper.select:
SELECT COALESCE(MAX(variant_no), 0) + 1
FROM mission
WHERE tier = #{tier}
  AND scope = #{scope}
  AND IFNULL(site_id, 0)  = IFNULL(#{siteId}, 0)
  AND IFNULL(verse_no, 0) = IFNULL(#{verseNo}, 0)
